+    className: attribute('class'),
+    status: attribute('data-status'),
+    tone: attribute('data-tone'),
+    text: badge[2]!.replace(/&(amp|lt|gt|quot|#x27);/g, (_, entity: string) => entities[entity]!),
+  };
+}
